import sys

MD = 998244353

def init(n):
    ch = [[0] * (n + 1) for _ in range(n + 1)]
    ch[0][0] = 1
    for i in range(1, n + 1):
        ch[i][0] = 1
        for j in range(1, i + 1):
            ch[i][j] = (ch[i - 1][j] + ch[i - 1][j - 1]) % MD
    return ch

def power(a, k):
    result = 1
    base = a
    exp = k
    while exp > 0:
        if exp & 1:
            result = (result * base) % MD
        base = (base * base) % MD
        exp >>= 1
    return result

def main():
    input_data = sys.stdin.read().strip().split()
    n, k, l = map(int, input_data)
    ch = init(n)

    pp = [0] * (2 * n + 1)
    qq = [0] * (2 * n + 1)
    aa = [0] * (2 * n + 1)

    pp[n] = power(2, n)
    for _ in range(n):
        for j in range(2 * n, 0, -1):
            pp[j] = (pp[j] - pp[j - 1]) % MD

    for j in range(2 * n + 1):
        aa[j] = pp[j]

    inv2 = (MD + 1) // 2
    for i in range(1, n - k + 1):
        for j in range(2 * n):
            qq[j] = (pp[j + 1] * inv2) % MD
        qq[2 * n] = 0
        for j in range(1, 2 * n + 1):
            qq[j] = (qq[j] + qq[j - 1]) % MD
        for j in range(2 * n + 1):
            pp[j] = (qq[j] - pp[j]) % MD
        a = ch[n][i]
        for j in range(2 * n + 1):
            aa[j] = (aa[j] + a * pp[j]) % MD

    total = 0
    for i in range(2 * n + 1):
        total = (total + aa[i] * power(i + 1, MD - 2)) % MD
    total = (total * l) % MD
    print(total)

if __name__ == "__main__":
    main()

